#![no_std]
use soroban_sdk::{
    contract, contracterror, contractimpl, contracttype, panic_with_error, token, Address, Env,
};

// Stored balances live for about 30 days, and every write renews them.
const LEDGER_THRESHOLD: u32 = 17_280;
const LEDGER_BUMP: u32 = 518_400;

#[contracttype]
pub enum DataKey {
    /// The Stellar Asset Contract address of the staked token, set by the constructor.
    Token,
    /// Sum of every user's stake.
    Total,
    /// One user's stake.
    Staked(Address),
}

#[contracterror]
#[derive(Copy, Clone, Debug, Eq, PartialEq)]
#[repr(u32)]
pub enum Error {
    InvalidAmount = 1,
    InsufficientStake = 2,
}

#[contract]
pub struct Staking;

#[contractimpl]
impl Staking {
    /// Runs once at deploy time. `token` is the Stellar Asset Contract address (XLM for native).
    pub fn __constructor(env: Env, token: Address) {
        env.storage().instance().set(&DataKey::Token, &token);
        env.storage().instance().set(&DataKey::Total, &0_i128);
        env.storage()
            .instance()
            .extend_ttl(LEDGER_THRESHOLD, LEDGER_BUMP);
    }

    /// Moves `amount` of the token from `user` into this contract and credits `user`.
    pub fn stake(env: Env, user: Address, amount: i128) {
        user.require_auth();
        if amount <= 0 {
            panic_with_error!(&env, Error::InvalidAmount);
        }

        let token = token_client(&env);
        token.transfer(&user, &env.current_contract_address(), &amount);

        let total = Self::total_staked(env.clone());
        set_total(&env, total + amount);
        set_staked(&env, &user, Self::staked(env.clone(), user.clone()) + amount);
    }

    /// Returns `amount` of the token from this contract to `user`. Fails if `user` has less staked.
    pub fn unstake(env: Env, user: Address, amount: i128) {
        user.require_auth();
        if amount <= 0 {
            panic_with_error!(&env, Error::InvalidAmount);
        }

        let current = Self::staked(env.clone(), user.clone());
        if current < amount {
            panic_with_error!(&env, Error::InsufficientStake);
        }
        let total = Self::total_staked(env.clone());
        set_total(&env, total - amount);
        set_staked(&env, &user, current - amount);

        let token = token_client(&env);
        token.transfer(&env.current_contract_address(), &user, &amount);
    }

    /// The amount `user` has staked.
    pub fn staked(env: Env, user: Address) -> i128 {
        let key = DataKey::Staked(user);
        if env.storage().persistent().has(&key) {
            env.storage().persistent().extend_ttl(&key, LEDGER_THRESHOLD, LEDGER_BUMP);
        }
        env.storage().persistent().get(&key).unwrap_or(0)
    }

    /// The amount staked by everyone together.
    pub fn total_staked(env: Env) -> i128 {
        env.storage().instance().get(&DataKey::Total).unwrap_or(0)
    }
}

fn token_client(env: &Env) -> token::TokenClient<'_> {
    let address: Address = env
        .storage()
        .instance()
        .get(&DataKey::Token)
        .expect("token not set");
    token::TokenClient::new(env, &address)
}

fn set_total(env: &Env, total: i128) {
    env.storage().instance().set(&DataKey::Total, &total);
    env.storage()
        .instance()
        .extend_ttl(LEDGER_THRESHOLD, LEDGER_BUMP);
}

fn set_staked(env: &Env, user: &Address, amount: i128) {
    let key = DataKey::Staked(user.clone());
    if amount == 0 {
        env.storage().persistent().remove(&key);
    } else {
        env.storage().persistent().set(&key, &amount);
        env.storage()
            .persistent()
            .extend_ttl(&key, LEDGER_THRESHOLD, LEDGER_BUMP);
    }
}

mod test;
EOF
cat > staking/src/test.rs <<'EOF'
#![cfg(test)]

use super::*;
use soroban_sdk::{testutils::Address as _, token::StellarAssetClient, Address, Env};

struct Setup<'a> {
    env: Env,
    client: StakingClient<'a>,
    token: token::TokenClient<'a>,
    sac: StellarAssetClient<'a>,
    contract_id: Address,
}

fn setup() -> Setup<'static> {
    let env = Env::default();
    env.mock_all_auths();

    let admin = Address::generate(&env);
    let sac_contract = env.register_stellar_asset_contract_v2(admin);
    let token_id = sac_contract.address();

    let contract_id = env.register(Staking, (&token_id,));
    let client = StakingClient::new(&env, &contract_id);
    let token = token::TokenClient::new(&env, &token_id);
    let sac = StellarAssetClient::new(&env, &token_id);

    Setup {
        env,
        client,
        token,
        sac,
        contract_id,
    }
}

#[test]
fn stake_moves_tokens_and_records_amount() {
    let s = setup();
    let user = Address::generate(&s.env);
    s.sac.mint(&user, &1_000);

    s.client.stake(&user, &400);

    assert_eq!(s.client.staked(&user), 400);
    assert_eq!(s.client.total_staked(), 400);
    assert_eq!(s.token.balance(&user), 600);
    assert_eq!(s.token.balance(&s.contract_id), 400);
}

#[test]
fn unstake_returns_tokens_and_reduces_amount() {
    let s = setup();
    let user = Address::generate(&s.env);
    s.sac.mint(&user, &1_000);
    s.client.stake(&user, &400);

    s.client.unstake(&user, &150);

    assert_eq!(s.client.staked(&user), 250);
    assert_eq!(s.client.total_staked(), 250);
    assert_eq!(s.token.balance(&user), 750);
    assert_eq!(s.token.balance(&s.contract_id), 250);
}

#[test]
fn unstake_everything_clears_the_user() {
    let s = setup();
    let user = Address::generate(&s.env);
    s.sac.mint(&user, &500);
    s.client.stake(&user, &500);

    s.client.unstake(&user, &500);

    assert_eq!(s.client.staked(&user), 0);
    assert_eq!(s.client.total_staked(), 0);
    assert_eq!(s.token.balance(&user), 500);
}

#[test]
fn unstake_more_than_staked_fails() {
    let s = setup();
    let user = Address::generate(&s.env);
    s.sac.mint(&user, &1_000);
    s.client.stake(&user, &100);

    let result = s.client.try_unstake(&user, &101);

    assert_eq!(result, Err(Ok(Error::InsufficientStake)));
    assert_eq!(s.client.staked(&user), 100);
    assert_eq!(s.client.total_staked(), 100);
    assert_eq!(s.token.balance(&user), 900);
}

#[test]
fn unstake_without_any_stake_fails() {
    let s = setup();
    let user = Address::generate(&s.env);

    let result = s.client.try_unstake(&user, &1);

    assert_eq!(result, Err(Ok(Error::InsufficientStake)));
}

#[test]
fn stake_rejects_non_positive_amounts() {
    let s = setup();
    let user = Address::generate(&s.env);
    s.sac.mint(&user, &100);

    assert_eq!(s.client.try_stake(&user, &0), Err(Ok(Error::InvalidAmount)));
    assert_eq!(s.client.try_stake(&user, &-5), Err(Ok(Error::InvalidAmount)));
    assert_eq!(s.client.total_staked(), 0);
}

#[test]
fn total_is_the_sum_of_all_users() {
    let s = setup();
    let alice = Address::generate(&s.env);
    let bob = Address::generate(&s.env);
    s.sac.mint(&alice, &300);
    s.sac.mint(&bob, &300);

    s.client.stake(&alice, &100);
    s.client.stake(&bob, &200);
    s.client.unstake(&alice, &40);

    assert_eq!(s.client.staked(&alice), 60);
    assert_eq!(s.client.staked(&bob), 200);
    assert_eq!(s.client.total_staked(), 260);
}

#[test]
fn nobody_has_anything_staked_at_first() {
    let s = setup();
    let user = Address::generate(&s.env);

    assert_eq!(s.client.staked(&user), 0);
    assert_eq!(s.client.total_staked(), 0);
}
