import { connection } from "next/server";
import { Suspense } from "react";
import { stakingContract } from "@/lib/contracts";
import { stellar } from "@/lib/stellar";

type Outcome = { value: string } | { error: string };

// Reads one value from the staking contract and turns a failure into a message.
async function read(call: () => Promise<{ result: bigint }>): Promise<Outcome> {
  try {
    const { result } = await call();
    // A bigint's string form is the plain integer, with no "n" suffix.
    return { value: result.toString() };
  } catch (error) {
    // Some network errors arrive with an empty message; fall back to their text, and say where we called.
    const reason = (error instanceof Error && error.message) || String(error) || "unknown error";
    return { error: `${reason} (RPC: ${stellar.rpcUrl ?? "not set"})` };
  }
}

async function TotalStaked() {
  // Call the contract when a request arrives, not while `next build` prerenders the page.
  await connection();
  const outcome = await read(() => stakingContract().total_staked());
  if ("error" in outcome) {
    return <p data-testid="total-error">Could not read the total staked: {outcome.error}</p>;
  }
  return (
    <p>
      Total staked: <span data-testid="total-staked">{outcome.value}</span>
    </p>
  );
}

async function StakedBy({ address }: { address: string }) {
  await connection();
  const outcome = await read(() => stakingContract().staked({ user: address }));
  if ("error" in outcome) {
    return (
      <p data-testid="staked-error">
        Could not read the stake of <code>{address}</code>: {outcome.error}
      </p>
    );
  }
  return (
    <p>
      Staked by <code>{address}</code>:{" "}
      <span data-testid="staked-amount">{outcome.value}</span>
    </p>
  );
}

export default async function StakingPage({
  searchParams,
}: {
  searchParams: Promise<{ address?: string | string[] }>;
}) {
  const { address } = await searchParams;
  const user = (Array.isArray(address) ? address[0] : address)?.trim();

  return (
    <main>
      <h1>Staking</h1>
      <p>
        Network: <code>{stellar.network}</code>
      </p>
      <Suspense fallback={<p>Reading the total…</p>}>
        <TotalStaked />
      </Suspense>
      {user ? (
        <Suspense fallback={<p>Reading the stake…</p>}>
          <StakedBy address={user} />
        </Suspense>
      ) : (
        <p>
          Add <code>?address=G…</code> to the URL to see one account&apos;s stake.
        </p>
      )}
    </main>
  );
}
